"""Generate a self-contained bilingual report from measured workflow-study files."""
from __future__ import annotations
import argparse
import hashlib
import json
from pathlib import Path

MODES = ('multi_agent','single_agent')


def extract(root):
    sources = []
    def read(path):
        raw = path.read_bytes()
        sources.append({'path':path.relative_to(root).as_posix(),'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw)})
        return json.loads(raw)
    data = {'manifest':read(root/'study-manifest.json'),'results':read(root/'study-results.json'),'arms':{}}
    if (root/'postprocess-results.json').exists():
        data['results']=read(root/'postprocess-results.json')
    if (root/'input-provenance/runtime-inspection.json').exists():
        data['runtime_inspection']=read(root/'input-provenance/runtime-inspection.json')
    if (root/'input-provenance/project-runtime-inspection.json').exists():
        data['project_runtime_inspection']=read(root/'input-provenance/project-runtime-inspection.json')
    if (root/'mac-cpu-reproduction/report.json').exists():
        data['cpu_reproduction']=read(root/'mac-cpu-reproduction/report.json')
    if (root/'local-publication/receipt.json').exists():
        data['local_publication']=read(root/'local-publication/receipt.json')
    if (root/'input-provenance/model-final-check.json').exists():
        data['model_final_check']=read(root/'input-provenance/model-final-check.json')
    if (root/'verifier/frozen-audit-snapshot.json').exists():
        snapshot=read(root/'verifier/frozen-audit-snapshot.json')
        data['system_model']={'source_snapshot_ref':snapshot['source_snapshot_ref'],
            'requirements':snapshot['requirements'],'kdps':snapshot['kdps'],
            'parameter_refs':snapshot.get('context_refs',{}).get('kdps',[])}
        data['verification']={'source_snapshot_ref':snapshot['source_snapshot_ref'],
            'screening':snapshot['contract']['screening'],
            'cpu_gpu_agreement':snapshot['contract']['cpu_gpu_agreement'],
            'objective':snapshot['plan']['objective'],
            'exploration_partition':snapshot['plan']['exploration'],
            'validation_partition':snapshot['plan']['validation']}
    for mode in MODES:
        folder = root/mode
        measured_rounds = {r['round']: r for r in data['results']['arms'][mode].get('rounds', [])}
        failures=[]
        for directory in sorted(folder.glob('round-*')):
            for name in ('rejected.json','failed.json','pending.json'):
                if (directory/name).exists():
                    failure=read(directory/name)
                    failures.append({'round':int(directory.name.split('-')[1]),
                        'status':failure['status'],'reason':failure.get('error',failure.get('reason')),
                        'call_metadata':[]})
                    for output_path in sorted((directory/'workflow').glob('*.result.json')):
                        output=read(output_path)
                        failures[-1]['call_metadata'].append({
                            **{k:v for k,v in output.items()if k!='final_answer'},
                            'structured_object':isinstance(output.get('final_answer'),dict)})
        rounds=[]
        for path in sorted(folder.glob('round-*/workflow/round-summary.json')):
            result=read(path)
            result['round']=int(path.parent.parent.name.split('-')[1])
            result['proposal']=read(path.parent.parent/'proposal.json')
            result['critic']=read(path.parent/'critic.result.json')['final_answer']
            result['evaluation']=measured_rounds.get(result['round'], {})
            result['calls']={k:{a:v for a,v in c.items() if a not in {'final_answer'}}for k,c in result['calls'].items()}
            rounds.append(result)
        candidates=[]
        for path in sorted(folder.glob('candidates/*/result.json')):
            r=read(path)
            candidates.append({k:r[k]for k in ('candidate_id','round','matrix_cell','score','all_screening_passed','numeric_gpu_verified','screening_pass_fraction','input_digest','controller_digest')})
            candidates[-1]['failure_metrics']=sorted({g['metric']for c in r['records']for g in c['screening']if not g['passed']})
        measured_by_id = {c['candidate_id']: c for c in candidates}
        for round_result in rounds:
            ids = round_result['evaluation'].get('candidate_ids', [])
            round_result['new_configurations'] = sum(c['round'] == round_result['round'] for c in candidates)
            round_result['reused_evaluations'] = sum(measured_by_id[id]['round'] < round_result['round'] for id in ids if id in measured_by_id)
        fresh=read(root/'fresh-audit'/mode/'result.json') if (root/'fresh-audit'/mode/'result.json').exists() else {'records':[]}
        known=read(folder/'validation/result.json') if (folder/'validation/result.json').exists() else {'records':[]}
        compiled=read(root/'fresh-audit'/mode/'compiled.json') if fresh['records'] else None
        cases=[]
        for record in fresh['records']:
            frames=[]
            for f in record['frames']:
                frames.append({**{k:f[k]for k in ('time_s','position_m','quaternion_wxyz','wheel_angle_rad','tilt_total_deg')},
                               'max_abs_wheel_rpm':max(abs(f[k])for k in ('wheel_x_rpm','wheel_y_rpm','wheel_z_rpm'))})
            cases.append({'id':f"{record['domain_id']} / {record['condition_id']} / {record['seed']}",
                'passed':all(g['passed']for g in record['screening']), 'summary':record['summary'],
                'agreement':record['paired_metrics']['state'],'paired_metrics':record['paired_metrics'],
                'screening':record['screening'],'frames':frames})
        data['arms'][mode]={'rounds':rounds,'failures':failures,'candidates':candidates,'cases':cases,'compiled':compiled,
            'known_confirmation_cases':[{'id':f"{r['domain_id']} / {r['condition_id']} / {r['seed']}",
                'summary':r['summary'],'screening':r['screening'],'agreement':r['paired_metrics']['state']}
                for r in known.get('records',[])],
            'execution_metadata':{'cpu':fresh['records'][0]['backend'],'gpu':fresh['records'][0].get('gpu_backend')}
                                 if fresh['records'] and 'backend' in fresh['records'][0] else None}
    historical=root/'historical-starting-validation'
    if (historical/'result.json').exists():
        prior=read(historical/'result.json')
        data['historical_starting_confirmation']={'source_note':'Historical public confirmation; already disclosed to both arms. Fresh starting audit is the matched new-seed comparison.',
            'cases':[{'id':f"{r['domain_id']} / {r['condition_id']} / {r['seed']}",
                'summary':r['summary'],'screening':r['screening'],'agreement':r['paired_metrics']['state']}
                for r in prior['records']]}
    baseline=root/'baseline-fresh-audit'
    if (baseline/'result.json').exists():
        result=read(baseline/'result.json')
        data['starting_design']={'result':{k:v for k,v in result.items()if k!='records'},
            'compiled':read(baseline/'compiled.json'),
            'cases':[{'id':f"{r['domain_id']} / {r['condition_id']} / {r['seed']}",
                      'summary':r['summary'],'agreement':r['paired_metrics']['state'],
                      'paired_metrics':r['paired_metrics'],
                      'passed':all(g['passed']for g in r['screening']),'screening':r['screening'],
                      'frames':[{'time_s':f['time_s'],'tilt_total_deg':f['tilt_total_deg'],
                                 'max_abs_wheel_rpm':max(abs(f[k])for k in ('wheel_x_rpm','wheel_y_rpm','wheel_z_rpm'))}
                                for f in r['frames']]}for r in result['records']]}
    if (root/'finalization.json').exists():
        data['finalization']=read(root/'finalization.json')
        study_id=data['results']['study_id']
        data['onepiece_refs']={'project_id':'balancing-cube',
            'analysis':{'id':study_id+'.paired-study','revision':'1'},
            'audit_snapshot':{'id':study_id+'.audit-snapshot','revision':'1'},
            'starting_audit':{'id':study_id+'.fresh.starting-design','revision':'1'},
            'selected_audits':{mode:{'id':study_id+'.fresh.'+mode,'revision':'2'}for mode in MODES}}
    # Compare exact case identities. Positional chart alignment must never pair
    # different seeds or conditions when an input file changes order.
    reference = data['arms'][MODES[0]]['cases']
    if len({case['id'] for case in reference}) != len(reference):
        raise ValueError('Duplicate fresh confirmation case identities')
    for group in [data['arms'][MODES[1]], *([data['starting_design']] if 'starting_design' in data else [])]:
        by_id = {case['id']: case for case in group['cases']}
        if len(by_id) != len(group['cases']) or set(by_id) != {case['id'] for case in reference}:
            raise ValueError('Fresh confirmation case identities differ across comparisons')
        group['cases'] = [by_id[case['id']] for case in reference]
    telemetry = root/'gpu-telemetry.jsonl'
    if telemetry.exists():
        raw = telemetry.read_bytes()
        sources.append({'path':telemetry.name,'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw)})
        samples = [json.loads(line) for line in raw.splitlines() if line.strip()]
        devices = {}
        for sample in samples:
            for device in sample.get('devices', []):
                devices.setdefault(device['id'], []).append(device)
        data['gpu_usage'] = {'samples':len(samples), 'errors':sum('error' in s for s in samples),
            'first_sample':samples[0]['timestamp'] if samples else None,
            'last_sample':samples[-1]['timestamp'] if samples else None,
            'devices':[{'id':id, 'name':rows[0]['name'], 'samples':len(rows),
                        'mean_sample_utilization_percent':sum(r['utilization_percent'] for r in rows)/len(rows),
                        'peak_sample_utilization_percent':max(r['utilization_percent'] for r in rows),
                        'peak_memory_used_mib':max(r['memory_used_mib'] for r in rows)}
                       for id,rows in sorted(devices.items())]}
    data['sources']=sources
    return data


