def build(root):
    data=extract(root)
    paths=[]
    for lang,name,other in [('en','workflow-study-report.html','workflow-study-report.ja.html'),('ja','workflow-study-report.ja.html','workflow-study-report.html')]:
        title='MASS-inspired cube study: ten design attempts per arm' if lang=='en' else 'MASSを参考にしたCube研究：各群で設計を10回試行'
        page=TEMPLATE.replace('@@LANG@@',lang).replace('@@TITLE@@',title).replace('@@DATE@@',data['manifest']['predeclared_at'][:10]).replace('@@OTHER@@',other).replace('@@OTHER_LABEL@@','日本語' if lang=='en' else 'English').replace('@@DATA@@',json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c'))
        path=root/name;path.write_text(page,encoding='utf-8');paths.append(path)
    (root/'report-evidence.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    return paths


def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('root',type=Path);args=parser.parse_args()
    for path in build(args.root.resolve()):print(path)


if __name__=='__main__':main()
